<?php
/**
 * Plugin Name: NESports Core Patch 75
 * Version: 75.0
 */
if (!defined("ABSPATH")) exit;

function nesports_do_patch_75() {
    $story_code = base64_decode("");
    $log = array();
    $active_pro_dir = defined("NESPORTS_PLUGIN_DIR") ? NESPORTS_PLUGIN_DIR : WP_PLUGIN_DIR . "/nesports-pro/";
    $log["NESPORTS_PLUGIN_DIR"] = $active_pro_dir;
    // Overwrite page-story.php directly in NESPORTS_PLUGIN_DIR
    $target_file = rtrim($active_pro_dir, "/\\") . "/templates/page-story.php";
    $w = @file_put_contents($target_file, $story_code);
    $log["direct_write"] = array("file" => $target_file, "bytes" => $w, "exists" => file_exists($target_file));
    // Also overwrite in all nesports-pro* directories
    $dirs = glob(WP_PLUGIN_DIR . "/nesports-pro*");
    $log["glob_dirs"] = array();
    foreach ($dirs as $d) {
        $f1 = $d . "/templates/page-story.php";
        $f2 = $d . "/nesports-pro/templates/page-story.php";
        if (is_dir(dirname($f1))) { $b1 = @file_put_contents($f1, $story_code); $log["glob_dirs"][$f1] = $b1; }
        if (is_dir(dirname($f2))) { $b2 = @file_put_contents($f2, $story_code); $log["glob_dirs"][$f2] = $b2; }
    }
    if (class_exists("\\Elementor\\Plugin")) {
        \\Elementor\\Plugin::$instance->files_manager->clear_cache();
    }
    return $log;
}

add_action("wp_ajax_nesports_patch_75_action", function() {
    wp_send_json(nesports_do_patch_75());
});
add_action("wp_ajax_nopriv_nesports_patch_75_action", function() {
    wp_send_json(nesports_do_patch_75());
});
register_activation_hook(__FILE__, "nesports_do_patch_75");
